import{_ as n,a0 as r,w as o,s as u,ao as p,I as s,a1 as l,A as e,x as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"Dialect：Linux 下的開源翻譯應用 | LCTT x X-CMD","titleTemplate":false,"description":"Dialect：Linux 下的開源翻譯應用 | LCTT (202110) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Dialect：Linux 下的開源翻譯應用 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Dialect：Linux 下的開源翻譯應用 | LCTT (202110) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202110/20210929 Dialect- An Open-Source Translation App for Linux","title":"Dialect：Linux 下的開源翻譯應用","tag":"202110","desc":""},"relativePath":"202110/20210929 Dialect- An Open-Source Translation App for Linux.md","filePath":"[post].md"}'),d={name:"202110/20210929 Dialect- An Open-Source Translation App for Linux.md"};function f(m,t,g,b,h,x){const a=r("Link");return o(),u("div",null,[t[24]||(t[24]=p('<h1 id="dialect-linux-下的開源翻譯應用" tabindex="-1">Dialect：Linux 下的開源翻譯應用 <a class="header-anchor" href="#dialect-linux-下的開源翻譯應用" aria-label="Permalink to “Dialect：Linux 下的開源翻譯應用”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202110/10/115724t5xgx8agu8asag0u.jpg" alt=""></p><blockquote><p>Dialect 是一個簡單明瞭的應用，可以讓你使用 Web 服務進行語言間的翻譯。想要了解更多的話，讓我們來一窺究竟。</p></blockquote><p>雖然你可以啓動 Web 瀏覽器並直接使用任何翻譯服務來完成工作，但桌面應用有時會派上用場。</p><p>Dialect 是一個簡單的翻譯應用，可以利用 Web 服務進行翻譯，同時給你一些額外的能力。</p><h3 id="使用谷歌翻譯和-libretranslate-的開源翻譯應用" tabindex="-1">使用谷歌翻譯和 LibreTranslate 的開源翻譯應用 <a class="header-anchor" href="#使用谷歌翻譯和-libretranslate-的開源翻譯應用" aria-label="Permalink to “使用谷歌翻譯和 LibreTranslate 的開源翻譯應用”">​</a></h3><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/09/dialect-screenshot.png?resize=800%2C331&amp;ssl=1" alt=""></p><p>Dialect 是一個主要為 GNOME 桌面定製的應用，但它在其他桌面環境下也應該能正常工作。</p><p>它可以讓你快速翻譯語言，同時還有一些額外的選項。</p><p>在其核心部分，你可以選擇谷歌翻譯或 LibreTranslate 翻譯服務。</p><p>儘管 LibreTranslate 達不到谷歌翻譯的準確性，但把它作為一個選項來切換是一個很好的補充。至少，對於一些基本的用法，如果用户不想利用谷歌的服務，你的桌面上就有一個備選方案。</p><h3 id="dialect-的特點" tabindex="-1">Dialect 的特點 <a class="header-anchor" href="#dialect-的特點" aria-label="Permalink to “Dialect 的特點”">​</a></h3><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/09/dialect-app-options.png?resize=800%2C470&amp;ssl=1" alt=""></p><p>除了切換翻譯服務外，你還能得到如下個功能：</p><ul><li>發音</li><li>文本到語音（TTS）功能（谷歌）</li><li>黑暗模式</li><li>翻譯快捷方式</li><li>實時翻譯</li><li>剪貼板按鈕可快速複製/粘貼</li><li>翻譯歷史（撤銷/重做）</li></ul><p>正如你在截圖中所注意到的，實時翻譯功能可能會因為濫用 API 而使你的 IP 地址被禁止使用服務。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/09/dialect-libretranslate.png?resize=800%2C326&amp;ssl=1" alt=""></p><p>我試着使用 LibreTranslate（如上圖所示）和谷歌翻譯，並啓用實時翻譯功能，它工作得很好。</p><p>也許，如果你經常依賴翻譯，你可能想避免這個實時翻譯。但是，對於我的臨時使用，在相當多的測試中，該服務並沒有導致 IP 地址被禁止。</p><p>重要的是要注意，如果你想，你可以指定一個自定義的 LibreTranslate 實例。默認情況下，它使用 “translate.astian.org” 作為實例。</p><p>你可能找不到一個單獨顯示的翻譯歷史區域，但窗口左上角的箭頭按鈕會讓你看到你以前的翻譯，以及翻譯設置。</p><p>所以，它也可以作為一個重做/撤銷的功能。</p><h3 id="在-linux-中安裝-dialect" tabindex="-1">在 Linux 中安裝 Dialect <a class="header-anchor" href="#在-linux-中安裝-dialect" aria-label="Permalink to “在 Linux 中安裝 Dialect”">​</a></h3>',23)),s("p",null,[l(a,{href:"https://flathub.org/apps/details/com.github.gi_lom.dialect"},{default:e(()=>[...t[0]||(t[0]=[i("Dialect",-1)])]),_:1}),t[3]||(t[3]=i(" 是以 ",-1)),l(a,{href:"https://itsfoss.com/what-is-flatpak/"},{default:e(()=>[...t[1]||(t[1]=[i("Flatpak",-1)])]),_:1}),t[4]||(t[4]=i(" 的形式提供的。所以，你應該能夠在你選擇的任何 Linux 發行版上安裝它。如果你是新手，你可能想看看我們的 ",-1)),l(a,{href:"https://itsfoss.com/flatpak-guide/"},{default:e(()=>[...t[2]||(t[2]=[i("Flatpak 指南",-1)])]),_:1}),t[5]||(t[5]=i(" 以獲得幫助。",-1))]),t[25]||(t[25]=p('<p>首先，添加 Flathub 倉庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>flatpak remote-add --if-not-exists flathub https://flathub.org/repo/flathub.flatpakrepo</span></span></code></pre></div><p>然後安裝應用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>flatpak install flathub com.github.gi_lom.dialect</span></span></code></pre></div><p>安裝後，在系統菜單中尋找它，並從那裏啓動它。</p>',5)),s("p",null,[t[7]||(t[7]=i("你也可以瀏覽它的 ",-1)),l(a,{href:"https://github.com/dialect-app/dialect/"},{default:e(()=>[...t[6]||(t[6]=[i("GitHub 頁面",-1)])]),_:1}),t[8]||(t[8]=i(" 瞭解更多信息。",-1))]),t[26]||(t[26]=s("hr",null,null,-1)),s("p",null,[t[10]||(t[10]=i("via: ",-1)),l(a,{href:"https://itsfoss.com/dialect/"},{default:e(()=>[...t[9]||(t[9]=[i("https://itsfoss.com/dialect/",-1)])]),_:1})]),s("p",null,[t[15]||(t[15]=i("作者：",-1)),l(a,{href:"https://itsfoss.com/author/ankush/"},{default:e(()=>[...t[11]||(t[11]=[i("Ankush Das",-1)])]),_:1}),t[16]||(t[16]=i(" 選題：",-1)),l(a,{href:"https://github.com/lujun9972"},{default:e(()=>[...t[12]||(t[12]=[i("lujun9972",-1)])]),_:1}),t[17]||(t[17]=i(" 譯者：",-1)),l(a,{href:"https://github.com/geekpi"},{default:e(()=>[...t[13]||(t[13]=[i("geekpi",-1)])]),_:1}),t[18]||(t[18]=i(" 校對：",-1)),l(a,{href:"https://github.com/wxy"},{default:e(()=>[...t[14]||(t[14]=[i("wxy",-1)])]),_:1})]),s("p",null,[t[21]||(t[21]=i("本文由 ",-1)),l(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[19]||(t[19]=[i("LCTT",-1)])]),_:1}),t[22]||(t[22]=i(" 原創編譯，",-1)),l(a,{href:"https://linux.cn/"},{default:e(()=>[...t[20]||(t[20]=[i("Linux中國",-1)])]),_:1}),t[23]||(t[23]=i(" 榮譽推出",-1))])])}const D=n(d,[["render",f]]);export{L as __pageData,D as default};
